/bin/zsh -lc "browser-cmd eval - <<'EOF'
(async () => {
const urls = [\"https://huggingface.co/api/models/Falconsai/medical_summarization\",\"https://huggingface.co/api/models?search=clinical&sort=createdAt&direction=-1&limit=30&full=true\",\"https://huggingface.co/api/models?filter=medical&sort=createdAt&direction=-1&limit=30&full=true\"];
return await Promise.all(urls.map(async u => {
 const r = await fetch(u);
 if ("'!r.ok) return {url:u,status:r.status};
 const d = await r.json();
 return {url:u,data:Array.isArray(d) ? d.map(x=>({id:x.id,createdAt:x.createdAt,tags:x.tags})) : {id:d.id,createdAt:d.createdAt,lastModified:d.lastModified}};
}));
})()
EOF'

